fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 as per the problem statement.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    for i in 2..n {
        // Safe from overflow by problem guarantee (F(i) < 2^31)
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}

